let udpText = (msg.payload || '').toString().trim();

// nur Channel 3 auswerten!
if (udpText.includes('_3_True')) {
    return { topic: 'udp_light_on', payload: true };
}

if (udpText.includes('_3_False')) {
    return { topic: 'udp_light_off', payload: false };
}

// ALLES andere ignorieren
return null;

const PRESENCE_HOLD_TIME_MS = 30 * 60 * 1000;
const DELAYED_OFF_TIME_MS = 2 * 60 * 1000;

function clearStoredTimer(timerName) {
    const activeTimer = context.get(timerName);
    if (activeTimer) {
        clearTimeout(activeTimer);
        context.set(timerName, null);
    }
}

function publishLightState(newLightState, reasonText) {
    context.set('xLightOutputActive', newLightState);

    node.send([
        {
            topic: 'light_command',
            payload: newLightState,
            reason: reasonText
        },
        {
            topic: 'light_status',
            payload: {
                xLightOutputActive: newLightState,
                xDelayedOffModeActive: !!context.get('xDelayedOffModeActive'),
                reason: reasonText
            }
        }
    ]);
}

function restartPresenceHoldTimer() {
    clearStoredTimer('presenceHoldTimerHandle');

    const timerHandle = setTimeout(() => {
        context.set('presenceHoldTimerHandle', null);
        context.set('xDelayedOffModeActive', false);

        if (context.get('xLightOutputActive')) {
            publishLightState(false, 'presence_hold_time_elapsed');
        }
    }, PRESENCE_HOLD_TIME_MS);

    context.set('presenceHoldTimerHandle', timerHandle);
}

function startDelayedOffTimer() {
    clearStoredTimer('presenceHoldTimerHandle');
    clearStoredTimer('delayedOffTimerHandle');

    context.set('xDelayedOffModeActive', true);

    const timerHandle = setTimeout(() => {
        context.set('delayedOffTimerHandle', null);
        context.set('xDelayedOffModeActive', false);

        if (context.get('xLightOutputActive')) {
            publishLightState(false, 'delayed_off_time_elapsed');
        }
    }, DELAYED_OFF_TIME_MS);

    context.set('delayedOffTimerHandle', timerHandle);
}

const xLightOutputActive = context.get('xLightOutputActive') || false;

switch (msg.topic) {
    case 'button_short_press': {
        clearStoredTimer('delayedOffTimerHandle');
        context.set('xDelayedOffModeActive', false);

        if (xLightOutputActive) {
            clearStoredTimer('presenceHoldTimerHandle');
            publishLightState(false, 'short_press_toggle_off');
        } else {
            publishLightState(true, 'short_press_toggle_on');
            restartPresenceHoldTimer();
        }
        return null;
    }

    case 'button_long_press': {
        if (xLightOutputActive) {
            startDelayedOffTimer();
            return [null, { topic: 'light_status', payload: 'Long press detected -> OFF in 2 minutes' }];
        }
        return [null, { topic: 'light_status', payload: 'Long press ignored because light is already OFF' }];
    }

    case 'presence_detected': {
        if (context.get('xLightOutputActive')) {
            if (context.get('xDelayedOffModeActive')) {
                return [null, { topic: 'light_status', payload: 'Presence ignored because delayed OFF mode is active' }];
            }
            restartPresenceHoldTimer();
            return [null, { topic: 'light_status', payload: 'Presence detected -> 30 minute timer restarted' }];
        }
        return [null, { topic: 'light_status', payload: 'Presence detected but light is OFF' }];
    }

    case 'udp_light_on': {
        clearStoredTimer('delayedOffTimerHandle');
        context.set('xDelayedOffModeActive', false);

        if (!context.get('xLightOutputActive')) {
            publishLightState(true, 'udp_light_on');
        } else {
            node.send([null, { topic: 'light_status', payload: 'UDP LIGHT ON received, light already ON' }]);
        }

        restartPresenceHoldTimer();
        return null;
    }

    case 'udp_light_off': {
        clearStoredTimer('presenceHoldTimerHandle');
        clearStoredTimer('delayedOffTimerHandle');
        context.set('xDelayedOffModeActive', false);

        if (context.get('xLightOutputActive')) {
            publishLightState(false, 'udp_light_off');
        }

        return [null, { topic: 'light_status', payload: 'UDP LIGHT OFF received' }];
    }

    case 'udp_all_off': {
        clearStoredTimer('presenceHoldTimerHandle');
        clearStoredTimer('delayedOffTimerHandle');
        context.set('xDelayedOffModeActive', false);

        if (context.get('xLightOutputActive')) {
            publishLightState(false, 'udp_all_off');
        }

        return [null, { topic: 'light_status', payload: 'UDP ALL OFF received' }];
    }

    case 'status_message_only': {
        return [null, { topic: 'light_status', payload: msg.payload }];
    }
}

return [null, { topic: 'light_status', payload: 'Unknown topic: ' + msg.topic }];

// BLINKER Phidget
// Input:
// msg.payload.enable     : true / false
// msg.payload.intervalMs : Blinkzeit in ms, optional
//
// Output passend fuer Phidget DigitalOutput:
// msg.topic   = "setDutyCycle"
// msg.payload = { dutyCycle: 0 | 1 }

let timer = context.get("blinkTimer");
let outputState = context.get("outputState") || 0;

let enable = false;
let intervalMs = 500;

if (typeof msg.payload === "object" && msg.payload !== null) {
    enable = !!msg.payload.enable;
    if (msg.payload.intervalMs !== undefined) {
        intervalMs = Number(msg.payload.intervalMs);
    } else {
        intervalMs = context.get("intervalMs") || 500;
    }
} else {
    node.warn("Expected msg.payload as object: { enable: true/false, intervalMs?: number }");
    return null;
}

if (!Number.isFinite(intervalMs) || intervalMs < 50) {
    intervalMs = 500;
}

context.set("intervalMs", intervalMs);

function buildPhidgetMessage(dutyCycle) {
    return {
        topic: "setDutyCycle",
        payload: {
            dutyCycle: dutyCycle
        }
    };
}

// STOP blinking
if (!enable) {
    if (timer) {
        clearInterval(timer);
        context.set("blinkTimer", null);
    }

    outputState = 0;
    context.set("outputState", outputState);
    node.status({ fill: "grey", shape: "ring", text: "stopped" });

    return buildPhidgetMessage(0);
}

// Restart timer cleanly
if (timer) {
    clearInterval(timer);
    context.set("blinkTimer", null);
}

// Start state: ON immediately
outputState = 1;
context.set("outputState", outputState);
node.status({ fill: "green", shape: "dot", text: "blinking " + intervalMs + " ms" });

const intervalHandle = setInterval(function () {
    let currentState = context.get("outputState") || 0;
    currentState = currentState ? 0 : 1;
    context.set("outputState", currentState);

    node.send(buildPhidgetMessage(currentState));
}, intervalMs);

context.set("blinkTimer", intervalHandle);

return buildPhidgetMessage(1);

finalize:
let timer = context.get("blinkTimer");
if (timer) {
    clearInterval(timer);
    context.set("blinkTimer", null);
}
context.set("outputState", 0);

