// Toggle nur bei Sequenz: _3_True -> _3_False

let lastState = context.get('lastState') || null;
let lightState = context.get('lightState') || false;

// nur relevante Topics
if (msg.topic !== 'udp_light_on' && msg.topic !== 'udp_light_off') {
    return null;
}

// True empfangen
if (msg.topic === 'udp_light_on') {
    context.set('lastState', 'on');
    return null;
}

// False nach True => Toggle!
if (msg.topic === 'udp_light_off' && lastState === 'on') {
    lightState = !lightState;
    context.set('lightState', lightState);
    context.set('lastState', 'off');

    return {
        topic: 'light_command',
        payload: lightState,
        reason: 'toggle_3_sequence'
    };
}

return null;
